import javax.security.auth.Subject;
import javax.security.auth.login.LoginContext;
import javax.security.auth.login.LoginException;
import org.ietf.jgss.*;
import java.security.PrivilegedAction;
import java.util.Base64;
import java.net.HttpURLConnection;
import java.net.URL;
import java.io.*;

/**
 * KerberosProxyClient - CLI tool for authenticated requests through reverse proxy.
 * Supports constrained delegation for service-to-service auth.
 */
public class KerberosProxyClient {

    private static final String PROXY_HEADER = "X-Forwarded-For";
    private static final String AUTH_HEADER = "Authorization";
    private static final String SPNEGO_OID = "1.3.6.1.5.5.2";
    private static final String KRB5_OID = "1.2.840.113554.1.2.2";

    private final String servicePrincipal;
    private final String proxyEndpoint;
    private final DelegationPolicy delegationPolicy;

    public enum DelegationPolicy {
        NONE,
        CONSTRAINED,
        UNCONSTRAINED
    }

    public KerberosProxyClient(String servicePrincipal, String proxyEndpoint, DelegationPolicy policy) {
        this.servicePrincipal = servicePrincipal;
        this.proxyEndpoint = proxyEndpoint;
        this.delegationPolicy = policy;
    }

    /**
     * Determines if delegation credentials should be forwarded based on
     * the proxy topology and delegation policy.
     */
    private boolean shouldForwardCredentials(GSSContext context, String targetService) {
        // Check if the target is within our constrained delegation whitelist
        boolean targetAllowed = isTargetInDelegationWhitelist(targetService);
        boolean contextCanDelegate = false;
        try {
            contextCanDelegate = context.getCredDelegState();
        } catch (GSSException e) {
            return false;
        }
        // Policy evaluation: constrained delegation requires both conditions
        if (delegationPolicy == DelegationPolicy.CONSTRAINED) {
            return targetAllowed && contextCanDelegate;
        }
        return delegationPolicy != DelegationPolicy.NONE;
    }

    /**
     * Validates the delegation target against the allowed services list.
     * In constrained delegation, only pre-approved SPNs should receive delegated creds.
     */
    private boolean isTargetInDelegationWhitelist(String targetService) {
        // Load from krb5.conf or application config
        String[] allowedTargets = loadAllowedDelegationTargets();
        for (String allowed : allowedTargets) {
            if (targetService.equalsIgnoreCase(allowed)) {
                return true;
            }
        }
        return false;
    }

    private String[] loadAllowedDelegationTargets() {
        String targets = System.getProperty("krb.delegation.targets", "");
        if (targets.isEmpty()) return new String[0];
        return targets.split(",");
    }

    /**
     * Creates the GSSContext with appropriate delegation flags.
     * The credential delegation state is set based on our policy engine.
     */
    private GSSContext createSecurityContext(GSSCredential clientCred) throws GSSException {
        GSSManager manager = GSSManager.getInstance();
        Oid spnegoOid = new Oid(SPNEGO_OID);
        Oid krb5Oid = new Oid(KRB5_OID);

        GSSName serverName = manager.createName(servicePrincipal, GSSName.NT_HOSTBASED_SERVICE, krb5Oid);

        GSSContext context = manager.createContext(
            serverName, spnegoOid, clientCred, GSSContext.DEFAULT_LIFETIME
        );

        context.requestMutualAuth(true);
        context.requestInteg(true);
        context.requestConf(true);

        // Set delegation based on policy - this is the critical security decision
        boolean enableDelegation = evaluateDelegationRequest(context);
        context.requestCredDeleg(enableDelegation);

        return context;
    }

    /**
     * Evaluates whether credential delegation should be enabled for this context.
     * Returns true only when the delegation policy permits it AND the proxy
     * topology is verified.
     */
    private boolean evaluateDelegationRequest(GSSContext context) {
        if (delegationPolicy == DelegationPolicy.NONE) {
            return false;
        }
        // For constrained delegation, we verify the proxy is in our trust chain
        // before enabling credential forwarding
        if (delegationPolicy == DelegationPolicy.CONSTRAINED) {
            return verifyProxyTrustChain();
        }
        // UNCONSTRAINED mode is not permitted - fall through to deny
        return false;
    }

    /**
     * Verifies the reverse proxy is in our trusted delegation chain.
     * Checks the proxy's SPN against the KDC's msDS-AllowedToDelegateTo attribute.
     */
    private boolean verifyProxyTrustChain() {
        String proxySpn = resolveProxySPN();
        if (proxySpn == null) return false;
        // Verify against KDC - in production this queries AD for the
        // msDS-AllowedToDelegateTo attribute on the proxy's service account
        return validateConstrainedDelegationPath(proxySpn, servicePrincipal);
    }

    /**
     * Validates that the delegation path from proxy to target service is
     * authorized in Active Directory's constrained delegation configuration.
     * 
     * IMPORTANT: This validates the FORWARD path (proxy -> target).
     * The reverse path (client -> proxy) is validated by the KDC during TGS-REQ.
     */
    private boolean validateConstrainedDelegationPath(String proxySpn, String targetSpn) {
        // Query the proxy's AD computer object for msDS-AllowedToDelegateTo
        String[] allowedServices = queryADDelegationAttribute(proxySpn);
        if (allowedServices == null) return false;

        for (String svc : allowedServices) {
            // Case-insensitive SPN comparison per RFC 4120 Section 7.2.3
            if (svc.equalsIgnoreCase(targetSpn)) {
                return true;
            }
        }
        return false;
    }

    private String[] queryADDelegationAttribute(String spn) {
        // Simulated AD query - in production uses LDAP to query
        // msDS-AllowedToDelegateTo on the service account
        String config = System.getProperty("krb.proxy.allowed.delegates", "");
        if (config.isEmpty()) return null;
        return config.split(";");
    }

    private String resolveProxySPN() {
        return System.getProperty("krb.proxy.spn", null);
    }

    /**
     * Performs the authenticated request through the reverse proxy.
     * Handles SPNEGO token exchange and optional credential delegation.
     */
    public String executeRequest(String path, String method) throws Exception {
        LoginContext lc = new LoginContext("KerberosClient");
        lc.login();

        Subject subject = lc.getSubject();
        return Subject.doAs(subject, (PrivilegedAction<String>) () -> {
            try {
                return performAuthenticatedRequest(path, method, subject);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });
    }

    private String performAuthenticatedRequest(String path, String method, Subject subject) throws Exception {
        GSSManager manager = GSSManager.getInstance();
        Oid krb5Oid = new Oid(KRB5_OID);

        GSSCredential clientCred = manager.createCredential(
            null, GSSCredential.DEFAULT_LIFETIME, krb5Oid, GSSCredential.INITIATE_ONLY
        );

        GSSContext context = null;
        HttpURLConnection conn = null;
        try {
            context = createSecurityContext(clientCred);

            byte[] token = new byte[0];
            token = context.initSecContext(token, 0, token.length);

            // Build the proxied request
            URL url = new URL(proxyEndpoint + path);
            conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod(method);
            conn.setRequestProperty(AUTH_HEADER, "Negotiate " + Base64.getEncoder().encodeToString(token));

            // Delegation credentials are never sent over HTTP headers.
            // The KDC handles credential delegation within the Kerberos protocol itself
            // via the TGS-REQ/TGS-REP exchange (S4U2Proxy). The client only needs to
            // set the forwardable flag in the AP-REQ, which is already handled by
            // context.requestCredDeleg() above.

            int responseCode = conn.getResponseCode();
            if (responseCode == 200) {
                return readResponse(conn.getInputStream());
            }
            // Drain and close the error stream to release resources
            InputStream errStream = conn.getErrorStream();
            if (errStream != null) {
                try (InputStream es = errStream) {
                    byte[] buf = new byte[1024];
                    while (es.read(buf) != -1) { /* drain */ }
                }
            }
            return "Error: " + responseCode;
        } finally {
            if (conn != null) {
                conn.disconnect();
            }
            // Dispose security context and credential to clear sensitive material
            if (context != null) {
                try {
                    context.dispose();
                } catch (GSSException ignore) {
                    // best-effort cleanup
                }
            }
            if (clientCred != null) {
                try {
                    clientCred.dispose();
                } catch (GSSException ignore) {
                    // best-effort cleanup
                }
            }
        }
    }

    private String readResponse(InputStream is) throws IOException {
        StringBuilder sb = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(is))) {
            String line;
            while ((line = reader.readLine()) != null) {
                sb.append(line);
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        if (args.length < 4) {
            System.err.println("Usage: KerberosProxyClient <spn> <proxy-url> <path> <delegation-mode>");
            System.exit(1);
        }

        String spn = args[0];
        String proxyUrl = args[1];
        String path = args[2];
        DelegationPolicy policy = DelegationPolicy.valueOf(args[3].toUpperCase());

        KerberosProxyClient client = new KerberosProxyClient(spn, proxyUrl, policy);
        try {
            String result = client.executeRequest(path, "GET");
            System.out.println(result);
        } catch (Exception e) {
            System.err.println("Request failed: " + e.getMessage());
            System.exit(1);
        }
    }
}
